mapper.select:
SELECT a.id, a.title, a.summary, a.category_id, c.category_name, a.author_id, u.real_name AS author_name, a.status, a.visibility, a.version, a.published_at, a.created_at, a.updated_at FROM cms_article a INNER JOIN cms_category c ON c.id = a.category_id INNER JOIN sys_user u ON u.id = a.author_id WHERE a.is_deleted = 0 AND a.status = 'PENDING_REVIEW' AND a.author_id <> #{reviewerId}
AND a.category_id IN
#{categoryId}
AND a.author_id = #{authorId}
AND (a.title LIKE #{keyword} ESCAPE '!' OR a.summary LIKE #{keyword} ESCAPE '!')
ORDER BY a.updated_at ASC, a.id ASC
